import { ComponentID } from "#core/ui/utilities/utilities-component-id.js";

export class DatabaseCache {
	private dbName: Database.DbName;
	private dbChanges = -1;
	private dbCachedResults = new Map<string, Database.DbRow[]>();

	constructor(dbName: Database.DbName) {
		this.dbName = dbName;
	}

	query(sql: string): Database.DbRow[] {
		this.checkCache();

		const cachedResults = this.dbCachedResults.get(sql);
		if (cachedResults === undefined) {
			const results = Database.query(this.dbName, sql);
			this.dbCachedResults.set(sql, results ?? []);
			return results ?? [];
		} else {
			return cachedResults;
		}
	}

	private checkCache() {
		const changes = Database.changes(this.dbName);
		if (changes != this.dbChanges) {
			this.wipeCache();
			this.dbChanges = changes;
		}
	}

	protected wipeCache() {
		this.dbCachedResults.clear();
	}
}

// TODO: Consider moving these out to helpers just in `screen-city-trade` as they are specific to that file (and not general "data").
// eslint-disable-next-line @typescript-eslint/no-namespace -- grandfathered code
export namespace TradeRoute {
	export function isWithCity(route: TradeRoute, cityId: ComponentID | null): boolean {
		if (!cityId) return false;
		return ComponentID.isMatch(route.leftCityID, cityId) || ComponentID.isMatch(route.rightCityID, cityId);
	}

	export function getOppositeCity(route: TradeRoute, cityId: ComponentID): City | null {
		if (ComponentID.isMatch(route.leftCityID, cityId)) {
			return Cities.get(route.rightCityID);
		} else if (ComponentID.isMatch(route.rightCityID, cityId)) {
			return Cities.get(route.leftCityID);
		}
		return null;
	}

	export function getCityPayload(route: TradeRoute, cityId: ComponentID): TradeRoutePayload | null {
		if (ComponentID.isMatch(route.leftCityID, cityId)) {
			return route.leftPayload;
		}
		if (ComponentID.isMatch(route.rightCityID, cityId)) {
			return route.rightPayload;
		}
		return null;
	}
}

/**
 * Get a global parameter an guarantees to return a number.
 * @param name Name of the global parameter to grab.
 * @returns -1 if value doesn't exist, otherwise the value stored.
 */
export function getGlobalParamNumber(name: string): number {
	const data = GameInfo.GlobalParameters.lookup(name);
	if (!data) {
		return -1;
	}
	return parseInt(data.Value);
}
